"Позвать друзей":"Chiama amici",
"Ловчие":"Cacciatori",
"Твоя команда":"La tua squadra",
"Изменить":"Modifica",
"Начать бой":"Inizia la battaglia",
"Здоровье босса растёт с каждым Ловчим, награда — у каждого своя.":"La salute del boss cresce con ogni Cacciatore; ognuno ha la sua ricompensa.",
"Ждём, когда хозяин начнёт бой…":"In attesa che l'host avvii la battaglia…",
