"Средиземноморье: Греция, Италия, Испания, Португалия, Турция":"Il Mediterraneo: Grecia, Italia, Spagna, Portogallo, Turchia",
"Скандинавская":"Norrena",
"Скандинавия, Исландия, Дания, Германия, Австрия, Прибалтика":"Scandinavia, Islanda, Danimarca, Germania, Austria, paesi baltici",
