"Ирландия, Британия, Франция, Бельгия, Нидерланды":"Irlanda, Gran Bretagna, Francia, Belgio, Paesi Bassi",
"Египетская":"Egizia",
"Египет и вся Африка, Аравия и Ближний Восток":"Egitto e tutta l’Africa, Arabia e Medio Oriente",
"Китайская":"Cinese",
"Китай, Монголия, Корея, Япония, Южная и Юго-Восточная Азия, Австралия и Океания":"Cina, Mongolia, Corea, Giappone, Asia meridionale e sud-orientale, Australia e Oceania",
"Ацтекская":"Azteca",
"Америка — от Аляски до Огненной Земли":"Le Americhe, dall'Alaska alla Terra del Fuoco",
"Оберег":"Talismano",
"Узелок с заговорённой травой. Бросай в духа, чтобы поймать.":"Un fagottino di erbe incantate. Lancialo a uno spirito per catturarlo.",
"Серебряный оберег":"Talismano d'argento",
"Серебро держит духов крепче. Шанс поимки ×1,5.":"L'argento trattiene meglio gli spiriti. Probabilità di cattura ×1,5.",
"Золотой оберег":"Talismano d'oro",
"Лучший оберег Ордена. Шанс поимки ×2.":"Il miglior talismano dell'Ordine. Probabilità di cattura ×2.",
"Духи обожают мёд. Успокаивает духа: шанс поимки ×1,5 на один бросок.":"Gli spiriti adorano il miele. Calma lo spirito: probabilità di cattura ×1,5 per un lancio.",
"Подорожник":"Piantaggine",
"Лист к ране — и полегчало. Возвращает духу четверть здоровья.":"Una foglia sulla ferita e va già meglio. Ridà allo spirito un quarto della salute.",
"Целебный отвар":"Decotto curativo",
"Травы Велеса, сваренные в воде из источника. Возвращает духу 60% здоровья.":"Erbe di Veles bollite in acqua di sorgente. Ridà allo spirito il 60% della salute.",
"Мёртвая вода":"Myortvaya Voda",
"Редкая сказочная вода, что сращивает самые тяжкие раны. Дух без сил поднимется на 4 часа раньше. Живых не лечит.":"Una rara acqua delle fiabe che richiude le ferite più gravi. Uno spirito esausto si rialza 4 ore prima. Non cura chi è ancora in piedi.",
"Живая вода":"Zhivaya Voda",
"Возвращает духу половину здоровья, а в разломе — лечит прямо в бою. Духа без сил не поднимет.":"Restituisce allo spirito metà della salute e nei varchi cura in piena battaglia. Non rialza uno spirito esausto.",
"Ладан":"Incenso",
"Дымок приманивает духов: 30 минут их вокруг вдвое больше.":"Il fumo attira gli spiriti: per 30 minuti intorno a te ce ne sono il doppio.",
"Дальний пропуск":"Pass a distanza",
"Грамота Ордена: закрыть Разлом до 5 км от тебя, не подходя к нему. Один Орден дарит каждый день.":"Lettera dell'Ordine: chiudi un Varco fino a 5 km da te senza avvicinarti. L'Ordine te ne regala uno al giorno.",
"Кольцо Ордена с воронкой дорог: шагни в любое место Атласа мира сразу, не дожидаясь перезарядки. Одни Врата дарят на седьмой день серии.":"Un anello dell’Ordine con un vortice di strade: vai subito in qualsiasi luogo dell’Atlante del mondo, senza aspettare la ricarica. Una viene regalata il settimo giorno della serie.",
"Настой опыта":"Infuso d'esperienza",
"Медовый настой на травах Велеса: сутки опыта на четверть больше.":"Infuso di miele con le erbe di Veles: per un giorno un quarto di PE in più.",
"Подарок":"Regalo",
"Узелок для друга: обереги, мёд, иногда кокон. Отправляется в «Меню → Друзья», раз в день каждому.":"Un fagottino per un amico: talismani, miele, a volte un bozzolo. Si invia da «Menu → Amici», uno al giorno per amico.",
