"Европа":"Europa",
"Здесь сходятся старые дороги Нави, Олимпа, Асгарда и холмов сидов — от Москвы до Дублина.":"Qui si incrociano le antiche strade della Nav, dell’Olimpo, di Asgard e delle colline dei sidhe, da Mosca a Dublino.",
"Азия":"Asia",
"От Уральских гор до Тихого океана. Отсюда родом небесные драконы Китая, а Сибирь и Средняя Азия — края славянских духов.":"Dai monti Urali all’oceano Pacifico. Da qui vengono i draghi celesti della Cina, e la Siberia e l’Asia centrale sono terre di spiriti slavi.",
"Африка":"Africa",
"Здесь, у Нила, стоят врата Дуата — родины египетских богов и духов пустыни.":"Qui, sul Nilo, si ergono le porte del Duat, patria degli dèi egizi e degli spiriti del deserto.",
"Северная Америка":"America del Nord",
"Земля пернатых змеев: из долины Мехико вышли ацтекские боги и духи.":"Terra dei serpenti piumati: dalla valle del Messico sono usciti gli dèi e gli spiriti aztechi.",
"Южная Америка":"America del Sud",
"Сельва, Анды и Амазонка. Ацтекские духи разлетелись и сюда — до самой Огненной Земли.":"Giungla, Ande e Amazzonia. Gli spiriti aztechi sono volati fin qui, fino alla Terra del Fuoco.",
"Австралия и Океания":"Australia e Oceania",
"Своих мифологий у Ордена здесь пока нет: сюда забредают китайские духи из соседней Юго-Восточной Азии.":"L’Ordine non ha ancora mitologie di qui: ci arrivano spiriti cinesi dal vicino Sud-est asiatico.",
"Антарктида":"Antartide",
"Здесь только пингвины и ледяные духи. Врата сюда не открываются — слишком холодно даже для Ловчих.":"Qui ci sono solo pinguini e spiriti del ghiaccio. Le Porte non si aprono fin qui: fa troppo freddo anche per i Cacciatori.",
"Миров духов всегда было много — у каждого народа свой: Навь у славян, царство Аида у греков, Асгард у скандинавов, холмы сидов у кельтов, Дуат у египтян, Небеса у китайцев, Миктлан у ацтеков. На местах их держал <b>Алатырь</b> — бел-горюч камень в середине всех миров. Каждые врата вели в свою землю, и духи не путали дорог.":"I mondi degli spiriti sono sempre stati tanti, ogni popolo aveva il suo: la Nav degli slavi, il regno dell'Ade dei greci, Asgard degli scandinavi, le colline dei sídhe dei celti, il Duat degli egizi, i Cieli dei cinesi, il Mictlan degli aztechi. A tenerli al loro posto era <b>Alatyr</b>, la pietra bianca ardente al centro di tutti i mondi. Ogni porta conduceva alla sua terra, e gli spiriti non sbagliavano mai strada.",
"Однажды осенней ночью Кощей Бессмертный решил спрятать свою смерть понадёжнее — прямо в сердце Алатыря. Камень треснул и раскололся. Все врата распахнулись разом, дороги между мирами спутались в клубок, и духи и боги семи мифологий высыпали в наш мир — каждый в своих краях. Эту ночь назвали <b>Перепутицей</b>. Кощей уверяет, что камень треснул сам, но Локи и Сунь Укун при этих словах почему-то хихикают.":"Una notte d'autunno Koschei l'Immortale decise di nascondere la sua morte in un posto più sicuro: proprio nel cuore di Alatyr. La pietra si incrinò e andò in pezzi. Tutte le porte si spalancarono insieme, le strade tra i mondi si aggrovigliarono come un gomitolo, e gli spiriti e gli dèi di sette mitologie si riversarono nel nostro mondo, ognuno nelle proprie terre. Quella notte fu chiamata <b>il Grande Groviglio</b>. Koschei giura che la pietra si è crepata da sola, ma Loki e Sun Wukong, chissà perché, ridacchiano ogni volta che lo dice.",
"Теперь Гиппокамп плещется в фонтанах Рима, Леший гуляет по подмосковным паркам, а Ниссе греет котов в подъездах Осло: каждый дух живёт у себя на родине, и за чужими приходится шагать через Врата. Разломы — трещины от расколотого камня — открываются в каждом городе, а боги ставят святилища у себя на родине: Святилища — на Руси, Храмы — в Греции, Пагоды — в Китае, Пирамиды — в Америке. Город рождает и своих, новых духов: Вайфайку, Трамвайника, Фонарника.":"Ora un Ippocampo sguazza nelle fontane di Roma, un Leshy passeggia nei parchi intorno a Mosca e un Nisse scalda i gatti nelle trombe delle scale di Oslo: ogni spirito vive nella sua terra d'origine, e per raggiungere gli altri bisogna attraversare le Porte. I varchi — crepe lasciate dalla pietra spezzata — si aprono in ogni città, e gli dèi erigono i loro santuari nella propria terra d'origine: santuari nella Rus', Templi in Grecia, Pagode in Cina, Piramidi in America. La città fa nascere anche i suoi spiriti nuovi: Vayfayka, Tramvaynik, Fonarnik.",
"Первыми с гостями поладили не учёные, а бабушки со своими оберегами: оказалось, оберег, сделанный с заботой, успокаивает любого духа, откуда бы тот ни был. Так появился <b>Орден Оберега</b> — союз Ловчих всех земель. Твоя задача — находить духов, ловить их оберегами, черпать силу из источников, закрывать разломы и собирать осколки Алатыря. Кто знает — может, однажды их хватит, чтобы распутать дороги домой.":"I primi ad andare d'accordo con i nuovi arrivati non furono gli scienziati, ma le nonne con i loro talismani: si scoprì che un talismano fatto con cura calma qualsiasi spirito, da qualunque parte venga. Così nacque l'<b>Ordine del Talismano</b>, un'unione di Cacciatori di tutte le terre. Il tuo compito: trovare gli spiriti, catturarli con i talismani, attingere forza dalle sorgenti, chiudere i varchi e raccogliere i frammenti di Alatyr. Chissà: forse un giorno basteranno a districare le strade di casa.",
"Ясно":"Sereno",
"Переменная облачность":"Poco nuvoloso",
"Пасмурно":"Coperto",
"Туман":"Nebbia",
"Дождь":"Pioggia",
"Снег":"Neve",
"Гроза":"Temporale",
"Ветрено":"Ventoso",
"Полнолуние":"Luna piena",
"Ночью духи Тени и Воды встречаются чаще, а Русалки и Навки выходят к людям.":"Di notte gli spiriti d'Ombra e d'Acqua sono più frequenti, e Rusalke e Navke si mostrano alla gente.",
"Новолуние":"Luna nuova",
