"Сильнейшие духи друга":"Gli spiriti più forti dell'amico",
"Награда за сегодня уже получена — сейчас это тренировка (+100 опыта за победу).":"La ricompensa di oggi è già stata riscossa: ora è un allenamento (+100 PE per vittoria).",
"Награда за первую победу за день: 800 опыта, ✦ 500, обереги и мёд, +1 ★ дружбы.":"Ricompensa per la prima vittoria del giorno: 800 PE, ✦ 500, talismani e miele, +1 ★ d'amicizia.",
"Поединок с другом":"Duello con un amico",
"Смена":"Cambia",
"Приём":"Mossa",
"Тапай — быстрая атака, она копит энергию.<br>Полная шкала — жми «Приём». Щиты берегут от приёмов хранителя.":"Tocca per l'attacco rapido: carica energia.<br>Barra piena: premi «Mossa». Gli scudi ti proteggono dalle mosse del guardiano.",
