"Победа не засчитана":"Vittoria non convalidata",
"Сервер не подтвердил этот бой. Проверь интернет и попробуй снова.":"Il server non ha confermato questa battaglia. Controlla la connessione e riprova.",
"Защитники «{0}» отступили — Святилище «{1}» свободно!":"I difensori di «{0}» si sono ritirati: il santuario «{1}» è libero!",
"Победа засчитана, но пока шёл бой, в Святилище сменились защитники.":"Vittoria convalidata, ma durante la battaglia i difensori del santuario sono cambiati.",
"«Достойно, Ловчий», — {0} склоняет голову. Святилище «{1}» освящено тобой до конца дня.":"«Degno di te, Cacciatore.» {0} china il capo. Hai consacrato il santuario «{1}» fino a fine giornata.",
"Победа!":"Vittoria!",
"Поставь своего защитника — и Святилище перейдёт твоему клану.":"Metti un tuo difensore e il santuario passerà al tuo clan.",
"Поражение":"Sconfitta",
"«Приходи, когда окрепнешь», — говорит {0}. Попробуй другую команду: смотри на стихии хранителя и береги щиты для его приёмов.":"«Torna quando sarai più forte», dice {0}. Prova un'altra squadra: guarda gli elementi del guardiano e tieni gli scudi per le sue mosse.",
"Хорошая тренировка! Награда за поединок с {0} сегодня уже получена.":"Bell'allenamento! La ricompensa per il duello con {0} oggi è già stata riscossa.",
"{0} жмёт тебе руку: «Честный бой!» Дружба крепнет.":"{0} ti stringe la mano: «Bella sfida!» L'amicizia si rafforza.",
"<b>+1 ★</b> дружбы":"<b>+1 ★</b> d'amicizia",
"Духи {0} оказались сильнее. Подбери команду против их стихий и попробуй снова — поединки с другом не ограничены.":"Gli spiriti di {0} sono stati più forti. Scegli una squadra contro i loro elementi e riprova: i duelli con gli amici sono illimitati.",
"Источник освобождён!":"Sorgente liberata!",
"Прислужник растворился в тумане. Один из его духов — омрачённый {0} — остался рядом. Его ещё можно спасти!":"Il servitore è svanito nella nebbia. Uno dei suoi spiriti, {0} offuscato, è rimasto qui. Puoi ancora salvarlo!",
