"Навь сильнее… пока":"La Nav è più forte… per ora",
"«{0}» — смеётся прислужник. Возьми духов, сильных против стихии «{1}», и возвращайся.":"«{0}», ride il servitore. Prendi spiriti forti contro l'elemento «{1}» e torna.",
