"Омрачённый Навью":"Offuscato dalla Nav",
"Фото":"Foto",
"Коснись оберега — он полетит в духа.":"Tocca il talismano: volerà verso lo spirito.",
"Смахни оберег вверх.":"Scorri il talismano verso l'alto.",
"Попади в кольцо, когда оно маленькое!":"Centra il cerchio quando è piccolo!",
"Сияющий дух!":"Spirito splendente!",
"<b>Зажми оберег и смахни вверх</b>, прямо к духу.<br>Чем быстрее свайп — тем дальше бросок.":"<b>Tieni premuto il talismano e scorri verso l'alto</b>, dritto sullo spirito.<br>Più veloce scorri, più lontano lanci.",
