"Ты и {0} теперь друзья! Стартовый подарок уже в сумке.":"Tu e {0} ora siete amici! Il regalo di benvenuto è già nella Borsa.",
"Лови духов вместе со мной в «Духолове»! Открой ссылку — мы сразу станем друзьями, а тебе достанется стартовый подарок:\n{0}":"Cattura spiriti con me in «Dukholov»! Apri il link: diventeremo subito amici e riceverai un regalo di benvenuto:\n{0}",
