"Друг у разлома нажал «Позвать друзей» и прислал код из 5 символов? Введи его — и в бой вместе, где бы ты ни был.":"Un amico presso un varco ha toccato «Chiama amici» e ti ha mandato un codice di 5 caratteri? Inseriscilo e combattete insieme, ovunque tu sia.",
