"Соперник — Ловчий с рейтингом ±{0} от твоего, а если такого нет — Ловчий Ордена. Рейтинг зависит от силы соперника · опыт — за первые {1} боёв дня":"Il tuo avversario è un Cacciatore con un punteggio entro ±{0} dal tuo o, se non c’è, un Cacciatore dell’Ordine. Il punteggio dipende dalla forza dell’avversario · esperienza per le prime {1} battaglie del giorno",
"Общая таблица всех Ловчих появится, когда к игре подключат облачный сервер.":"La classifica di tutti i Cacciatori apparirà quando il gioco sarà collegato al server cloud.",
