"начало пути":"inizio del cammino",
"Получено в этом сезоне":"Ottenuto in questa stagione",
"Рейтинг зависит от соперника: победа над сильным даёт много, над слабым — мало; поражение от слабого стоит дороже. В твоей лиге победа над равным — +{0}, поражение — −{1}; чем выше лига, тем медленнее подъём. Из лиги можно выпасть. Награду за лигу дают один раз за сезон. В начале нового сезона рейтинг сверх {2} срезается наполовину, а за высшую лигу прошлого сезона Орден дарит сундук. В лигах «{3}», «{4}» и «{5}» — ещё и амулет.":"Il punteggio dipende dall'avversario: battere uno forte dà molto, uno debole poco; perdere con uno debole costa di più. Nella tua lega vincere contro un pari vale +{0}, perdere −{1}; più alta la lega, più lenta la salita. Si può retrocedere. Il premio di una lega si riceve una volta a stagione. All'inizio di una nuova stagione il punteggio oltre {2} si dimezza, e per la lega più alta della stagione scorsa l'Ordine regala un forziere. Nelle leghe «{3}», «{4}» e «{5}» c'è anche un amuleto.",
"<b>{0}-е место</b> из {1} в сезоне":"<b>{0}° posto</b> su {1} in stagione",
"Сыграй бой, чтобы попасть в таблицу":"Gioca una battaglia per entrare in classifica",
"Карточка откроется после обновления сервера":"La scheda si aprirà dopo l'aggiornamento del server",
"Неизвестный ход":"Azione sconosciuta",
"Слишком много ударов сразу":"Troppi colpi insieme",
"Неизвестный приём":"Mossa speciale sconosciuta",
"Этот приём не выучен":"Questa mossa non è stata imparata",
"Неверный приём":"Mossa non valida",
"Этого духа не выпустить":"Questo spirito non può scendere in campo",
"Бросай оберег, когда кольцо сжимается: «Отлично!» даёт больше опыта и шанс поимки.":"Lancia il talismano quando il cerchio si restringe: un «Ottimo!» dà più esperienza e probabilità di cattura.",
"Источники наполняются снова через несколько минут — прогулка по кругу приносит припасы.":"Le sorgenti si ricaricano dopo qualche minuto: un giro a piedi ti porta provviste.",
"Спутник ходит с тобой и находит эссенцию своего семейства.":"Il compagno cammina con te e trova essenza della sua famiglia.",
"В Лиге дерутся живые Ловчие: победа над сильным соперником даёт больше рейтинга, чем над слабым.":"Nella Lega combattono Cacciatori veri: battere un avversario forte dà più punteggio che batterne uno debole.",
"Разломы открываются у Святилищ каждый час: собери команду из трёх духов.":"I varchi si aprono presso i santuari ogni ora: forma una squadra di tre spiriti.",
"Сияющие духи редки — их выдают искры вокруг.":"Gli spiriti splendenti sono rari: li tradiscono le scintille intorno.",
"Коконы греются шагами: одновременно можно греть три.":"I bozzoli si scaldano con i passi: puoi scaldarne tre alla volta.",
"Ходи джойстиком: лёгкий наклон — шаг, до упора — бег. Километры для коконов считаются так же.":"Muoviti con il joystick: una leggera inclinazione è camminare, fino in fondo è correre. I chilometri contano per i bozzoli allo stesso modo.",
"Атлас мира переносит в любой уголок Земли раз в полчаса, а Врата Перепутицы — сразу.":"L’Atlante del mondo ti porta in qualsiasi angolo della Terra ogni mezz’ora; le Porte del Grande Groviglio, subito.",
"Задания дня обновляются в полночь, а за все три ждёт Сундук дня.":"Le missioni del giorno si rinnovano a mezzanotte, e completandole tutte e tre ottieni il Forziere del giorno.",
"Поставь защитника в Святилище своего клана — он принесёт искры.":"Metti un difensore su un santuario del tuo clan: ti porterà scintille.",
"Погода усиливает духов своей стихии: в дождь чаще встречаются водные.":"Il meteo potenzia gli spiriti del suo elemento: con la pioggia si incontrano più spiriti d'Acqua.",
"Привяжи вход через Google, Яндекс или Telegram — прогресс не потеряется при смене телефона.":"Collega l'accesso con Google, Yandex o Telegram: non perderai i progressi cambiando telefono.",
