"Можно перейти в ту учётную запись — тогда текущий гостевой прогресс на этом устройстве останется в прежней учётной записи, вернуться в неё будет нельзя. Или привязать этот вход к текущему Ловчему.":"Puoi passare a quell’account: i progressi da ospite su questo dispositivo restano nel vecchio account e non potrai tornarci. Oppure collegare questo accesso al tuo Cacciatore attuale.",
