"поимка духа стихии «{0}» — 3 очка":"cattura di uno spirito di elemento «{0}»: 3 punti",
"источник — 2 очка":"sorgente: 2 punti",
"разлом — 10 очков":"varco: 10 punti",
"победа в святилище — 6 очков":"vittoria a un santuario: 6 punti",
"путь и коконы — вдвое":"cammino e bozzoli: doppio",
"Прошлая неделя — награды ещё ждут":"Settimana scorsa: le ricompense ti aspettano ancora",
"Все Ловчие вместе копят очки: {0}.":"Tutti i Cacciatori accumulano punti insieme: {0}.",
" На этой неделе {0}.":" Questa settimana: {0}.",
"Цель растёт с числом участников. Награду ступени получает каждый, кто внёс нужное число очков.":"L'obiettivo cresce con il numero di partecipanti. La ricompensa di un gradino va a chiunque abbia contribuito con i punti richiesti.",
"Общее дело: ступень {0}":"Impresa comune: gradino {0}",
"Орден благодарит тебя за помощь!":"L'Ordine ti ringrazia per l'aiuto!",
"Послушник":"Novizio",
"Следопыт":"Segugio",
"Ведун":"Veggente",
"Поимка духов":"Cattura di spiriti",
"Обереги, мёд, источники и коконы":"Talismani, miele, sorgenti e bozzoli",
"Кампания, задания дня и поручения источников":"Campagna, missioni del giorno e incarichi delle sorgenti",
"Лавка Ордена":"Bottega dell'Ordine",
"Обереги, мёд и живая вода":"Talismani, miele e Zhivaya Voda",
"Коды дружбы и ежедневные подарки":"Codici amicizia e regali quotidiani",
"Награды за обычную игру":"Premi per il gioco di tutti i giorni",
"Бой командой из трёх духов с хранителем Разлома":"Battaglia di una squadra di tre spiriti contro il custode del Varco",
"Святилища предков":"I santuari degli antenati",
"Поединки 3 на 3 с хранителями":"Duelli 3 contro 3 con i guardiani",
"Можно писать сообщения":"Puoi scrivere messaggi",
"Освобождай захваченные источники":"Libera le sorgenti conquistate",
"Бои в реальном времени, рейтинг и лиги":"Battaglie in tempo reale, punteggio e leghe",
"Клан своей мифологии — знамя над святилищами":"Un clan della tua mitologia: il suo stendardo sui santuari",
"Продажа и покупка духов":"Compravendita di spiriti",
"Шанс поимки ×1,5":"Probabilità di cattura ×1,5",
"Шанс поимки ×2":"Probabilità di cattura ×2",
"Поручения источников · {0}":"Incarichi delle sorgenti · {0}",
"Особые встречи и награды":"Incontri e ricompense speciali",
"Плащ «{0}»":"Mantello «{0}»",
"Для облика Ловчего":"Per l'aspetto del Cacciatore",
"Глаза «{0}»":"Occhi «{0}»",
"Пробуждение: звезда {0}":"Risveglio: stella {0}",
"Предел уровня духа +{0} за осколки Алатыря":"Livello massimo dello spirito +{0} per frammenti di Alatyr",
"Вершина пути":"La vetta del cammino",
"Максимальный уровень Ловчего":"Livello massimo da Cacciatore",
"Сегодня получено {0} опыта — полностью до {1}":"Oggi hai ottenuto {0} PE: pieni fino a {1}",
"Сегодня получено {0} опыта — дальше вполовину до {1}":"Oggi hai ottenuto {0} PE: da qui a metà fino a {1}",
"Сегодня получено {0} опыта — дальше на четверть":"Oggi hai ottenuto {0} PE: da qui a un quarto",
"Опыт отдыха: следующие {0} опыта — вдвое":"PE di riposo: i prossimi {0} PE raddoppiati",
"За день опыт идёт полностью до {0}, дальше до {1} — вполовину, сверх — на четверть. Обучение и знаки Ордена дают опыт всегда полностью. За каждый день без игры копится опыт отдыха ({2}, не больше чем за {3} {4}): пока он есть, опыт вдвое.":"Nella giornata i PE arrivano pieni fino a {0}, poi fino a {1} a metà, oltre a un quarto. Il tutorial e i distintivi dell'Ordine danno sempre PE pieni. Per ogni giorno senza giocare si accumulano PE di riposo ({2}, al massimo per {3} {4}): finché ci sono, i PE raddoppiano.",
"Звание «{0}»":"Titolo «{0}»",
"Ты здесь":"Sei qui",
"Ты прошёл весь путь!":"Hai percorso tutto il cammino!",
"До {0} уровня — {1} опыта":"Al livello {0}: {1} PE",
"дальше: {0} на {1}":"poi: {0} al liv. {1}",
"Опыт дают поимки, источники, разломы, святилища и задания. С уровнем растут и твои духи: их можно усиливать до уровня Ловчего +5.":"L'esperienza arriva da catture, sorgenti, varchi, santuari e missioni. Con il tuo livello crescono anche i tuoi spiriti: puoi potenziarli fino al tuo livello da Cacciatore +5.",
"С {0} уровня духов можно пробуждать: каждая звезда поднимает предел уровня духа ещё на {1}, до {2}.":"Dal livello {0} puoi risvegliare gli spiriti: ogni stella alza il loro livello massimo di altri {1}, fino a {2}.",
"Ищу настоящие места вокруг — Источники и Святилища появятся через несколько секунд":"Cerco luoghi reali qui intorno: Sorgenti e santuari appariranno tra qualche secondo",
"Сервер мест не ответил":"Il server dei luoghi non ha risposto",
"Посылка из Ордена":"Un pacco dall'Ordine",
"Поблизости пока нет ни одного Источника, поэтому Орден раз в день присылает припасы: {0}.":"Qui vicino non c'è ancora nessuna Sorgente, quindi l'Ordine ti manda provviste una volta al giorno: {0}.",
