"Там, где Алатырь дал трещину, из-под земли бьёт вода Перепутицы. У Источников Ловчие всех земель черпают обереги и припасы.":"Dove l’Alatyr si è incrinato, l’acqua del Grande Groviglio sgorga dalla terra. Alle Sorgenti i Cacciatori di ogni terra attingono talismani e provviste.",
