"Перепутица спутала дороги мира, и Орден Оберега открыл Ловчим Врата: выбери в Атласе мира любой уголок Земли — там и начнёшь охоту. По карте ходи джойстиком, а в новые края шагай через Атлас. Настоящее местоположение телефона игре не нужно. Прогресс хранится на сервере игры и доступен только тебе; сервер проверяет каждое действие, поэтому нужен интернет. Места на карте и погода загружаются для выбранного района у OpenStreetMap и Open-Meteo (погоду можно выключить в настройках).":"Il Grande Groviglio ha aggrovigliato le strade del mondo e l’Ordine del Talismano ha aperto le Porte ai Cacciatori: scegli nell’Atlante del mondo un angolo qualsiasi della Terra, lì inizierà la tua caccia. Sulla mappa ti muovi con il joystick, e nelle nuove terre arrivi attraverso l’Atlante. Il gioco non ha bisogno della posizione reale del telefono. I progressi sono salvati sul server del gioco e sono accessibili solo a te; il server controlla ogni azione, per questo serve internet. I luoghi sulla mappa e il meteo della zona scelta vengono caricati da OpenStreetMap e Open-Meteo (il meteo si può disattivare nelle impostazioni).",
"Уже играешь?":"Giochi già?",
"Войди — и твой прогресс откроется на этом устройстве":"Accedi e i tuoi progressi si apriranno su questo dispositivo",
"Назови себя":"Dicci il tuo nome",
"Коснись, чтобы попробовать ещё раз":"Tocca per riprovare",
"Новое приложение":"Nuova app",
"Игра переехала на свой сервер в России — <b>duholov.ru</b>. Для этого вышло новое приложение: его нужно установить заново.":"Il gioco si è trasferito sul suo server in Russia: <b>duholov.ru</b>. Per questo è uscita una nuova app da installare da capo.",
"Привяжи вход: Меню → Настройки → Учётная запись (Google, Яндекс, VK, Telegram или почта). Без этого прогресс гостя не перенесётся.":"Collega un accesso: Menu → Impostazioni → Account (Google, Yandex, VK, Telegram o e-mail). Senza questo, i progressi da ospite non verranno trasferiti.",
"Удали это приложение.":"Disinstalla questa app.",
